/**
 * Get a paginated list of repairs with filtering and sorting.
 *
 * Enriches each repair with customer name, bicycle brand/model/color for display.
 * Supports filtering by status, assigned worker, and pickup date range.
 *
 * @param filters - Optional filter criteria
 * @param page - Page number (1-indexed)
 * @param pageSize - Number of items per page
 * @returns Paginated repair list with metadata
 */
export async function getRepairsList(
  filters: RepairListFilters = {},
  page: number = 1,
  pageSize: number = 20,
): Promise<PaginatedRepairs> {
  const offset = (page - 1) * pageSize
  const client = sqliteDb as Database.Database

  // Build WHERE clause and params for raw SQL
  const whereParts: string[] = []
  const params: unknown[] = []

  if (filters.status) {
    whereParts.push('r.status = ?')
    params.push(filters.status)
  }

  if (filters.assignedTo !== undefined && filters.assignedTo !== null) {
    whereParts.push('r.assigned_to = ?')
    params.push(filters.assignedTo)
  } else if (filters.assignedTo === null) {
    // Explicitly filter for unassigned repairs
    whereParts.push('r.assigned_to IS NULL')
  }

  // Pickup date filtering
  const now = Date.now()
  if (filters.pickupDateFilter === 'today') {
    const todayStart = new Date(now).setHours(0, 0, 0, 0)
    const todayEnd = new Date(now).setHours(23, 59, 59, 999)
    whereParts.push('r.pickup_date >= ? AND r.pickup_date <= ?')
    params.push(todayStart, todayEnd)
  } else if (filters.pickupDateFilter === 'this_week') {
    const today = new Date(now)
    const dayOfWeek = today.getDay()
    // Monday is 0 for our purposes (ISO week start)
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek
    const weekStart = new Date(today)
    weekStart.setDate(today.getDate() + mondayOffset)
    weekStart.setHours(0, 0, 0, 0)
    const weekEnd = new Date(weekStart)
    weekEnd.setDate(weekStart.getDate() + 6)
    weekEnd.setHours(23, 59, 59, 999)
    whereParts.push('r.pickup_date >= ? AND r.pickup_date <= ?')
    params.push(weekStart.getTime(), weekEnd.getTime())
  }

  // Date-range filtering: uses plannedDate with fallback to createdAt (COALESCE)
  if (filters.from !== undefined) {
    whereParts.push('COALESCE(r.planned_date, r.created_at) >= ?')
    params.push(filters.from)
  }
  if (filters.to !== undefined) {
    whereParts.push('COALESCE(r.planned_date, r.created_at) <= ?')
    params.push(filters.to)
  }

  // Status-in filtering: comma-separated list of statuses to include
  if (filters.statusIn && filters.statusIn.length > 0) {
    const placeholders = filters.statusIn.map(() => '?').join(',')
    whereParts.push(`r.status IN (${placeholders})`)
    params.push(...filters.statusIn)
  }

  // Bicycle IDs filtering — used for customer detail panel (repairs across all customer bikes)
  if (filters.bicycleIds && filters.bicycleIds.length > 0) {
    const placeholders = filters.bicycleIds.map(() => '?').join(',')
    whereParts.push(`r.bicycle_id IN (${placeholders})`)
    params.push(...filters.bicycleIds)
  }

  const whereClause = whereParts.length > 0 ? `WHERE ${whereParts.join(' AND ')}` : ''

  // Get total count for pagination (use alias r to match whereParts)
  const [countRow] = client.prepare(`SELECT COUNT(*) AS cnt FROM repairs r ${whereClause}`).all(...params) as Array<{ cnt: number }>
  const total = Number(countRow.cnt)
  const totalPages = Math.ceil(total / pageSize) || 1

  // Fetch enriched repair list with customer name and bicycle info
  const rows = client.prepare(`
    SELECT
      r.id,
      r.bicycle_id,
      r.assigned_to,
      r.status,
      r.customer_notes,
      r.internal_notes,
      r.hold_reason,
      r.hold_reason_note,
      r.planned_date,
      r.pickup_date,
      r.completed_at,
      r.created_at,
      c.first_name || ' ' || c.last_name AS customer_name,
      b.brand AS bicycle_brand,
      b.model AS bicycle_model,
      b.color AS bicycle_color
    FROM repairs r
    INNER JOIN bicycles b ON r.bicycle_id = b.id
    LEFT JOIN customers c ON b.customer_id = c.id
    ${whereClause}
    ORDER BY r.planned_date DESC NULLS LAST, r.created_at DESC
    LIMIT ? OFFSET ?
  `).all(...params, pageSize, offset) as Array<{
    id: string
    bicycle_id: string
    assigned_to: string | null
    status: string
    customer_notes: string | null
    internal_notes: string | null
    hold_reason: string | null
    hold_reason_note: string | null
    planned_date: number | null
    pickup_date: number | null
    completed_at: number | null
    created_at: number
    customer_name: string | null
    bicycle_brand: string
    bicycle_model: string
    bicycle_color: string | null
  }>

  const repairList: RepairDetailWithCustomer[] = rows.map((row) => ({
    id: row.id,
    bicycleId: row.bicycle_id,
    assignedTo: row.assigned_to,
    status: row.status as RepairStatus,
    customerNotes: row.customer_notes,
    internalNotes: row.internal_notes,
    holdReason: row.hold_reason as HoldReason | null,
    holdReasonNote: row.hold_reason_note,
    plannedDate: row.planned_date,
    pickupDate: row.pickup_date,
    completedAt: row.completed_at,
    createdAt: row.created_at,
    customerName: row.customer_name || null,
    bicycleBrand: row.bicycle_brand,
    bicycleModel: row.bicycle_model,
    bicycleColor: row.bicycle_color,
  }))

  return {
    repairs: repairList,
    total,
    page,
    pageSize,
    totalPages,
  }
}

