/**
 * Create a new repair via the intake flow.
 *
 * This is an atomic operation that:
 * 1. Validates the intake input schema
 * 2. Creates a new customer if customerMode='new'
 * 3. Creates a new bicycle if bicycleMode='create_new' (linked to the customer)
 * 4. Creates the repair record with status='intake' and assignedTo=NULL
 * 5. Records the initial status transition in the audit trail
 *
 * @param input - Validated intake input from the form
 * @returns The created RepairDetail
 */
export async function createRepairIntake(input: RepairIntakeInput): Promise<RepairDetail> {
  // Validate against the combined schema
  const validated = repairIntakeSchema.parse(input)

  let customerId: string

  // Step 1: Handle customer (existing or inline creation)
  if (validated.customerMode === 'new') {
    const newCustomerData = validated.newCustomer as Parameters<typeof repoCreateNewCustomer>[0]
    customerId = await repoCreateNewCustomer(newCustomerData)
  } else {
    // existing mode — verify the customer exists
    const existingCustomer = await repoFindCustomerById(validated.existingCustomerId!)
    if (!existingCustomer) {
      throw new RepairNotFoundError(`Customer not found: ${validated.existingCustomerId}`)
    }
    customerId = validated.existingCustomerId!
  }

  // Step 2: Handle bicycle (select existing or inline creation)
  let bicycleId: string

  if (validated.bicycleMode === 'create_new') {
    const newBicycleData = createIntakeBicycleSchema.parse(validated.newBicycle!)
    bicycleId = await repoCreateNewBicycle(newBicycleData, customerId)
  } else {
    // select_existing mode — verify the bicycle exists and belongs to the customer
    if (!validated.existingBicycleId) {
      throw new Error('existingBicycleId is required when selecting an existing bicycle')
    }

    const [bicycle] = await db
      .select()
      .from(bicycles)
      .where(eq(bicycles.id, validated.existingBicycleId!))

    if (!bicycle) {
      throw new RepairNotFoundError(`Bicycle not found: ${validated.existingBicycleId}`)
    }

    // Verify the bicycle belongs to the selected customer (or is shop inventory)
    if (bicycle.customerId !== null && bicycle.customerId !== customerId) {
      throw new Error('Selected bicycle does not belong to the chosen customer')
    }

    bicycleId = validated.existingBicycleId!
  }

  // Step 3: Create the repair record
  const repairData = {
    id: crypto.randomUUID(),
    bicycleId,
    assignedTo: null, // deferred assignment — manager assigns later
    status: 'intake',
    customerNotes: validated.customerNotes || null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: (validated as any).plannedDate ?? null,
    pickupDate: (validated as any).pickupDate ?? null,
    completedAt: null,
  }

  const created = await repoCreateRepair(repairData)

  // Step 4: Record initial status in audit trail
  await repoRecordStatusTransition(created.id, 'intake')

  return toRepairDetail(created)
}

/**
 * Transition a repair to a new status.
 *
 * Validates the transition against the allowed state machine, records the
 * hold reason/note if applicable, and updates the repair record atomically.
 *
 * @param id - Repair identifier
 * @param input - Target status with optional hold reason details
 * @returns The updated RepairDetail
 */
export async function transitionRepairStatus(
  id: string,
  input: TransitionRepairStatusInput,
): Promise<RepairDetail> {
  // Validate the transition input
  const validated = transitionRepairStatusSchema.parse(input)

  // Look up current repair state
  const current = await repoFindRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }

  const currentStatus = current.status as RepairStatus
  const targetStatus = validated.targetStatus as RepairStatus

  // Validate the transition is allowed
  validateTransition(currentStatus, targetStatus)

  // If transitioning to on_hold, require holdReason and holdReasonNote
  if (targetStatus === 'on_hold') {
    if (!validated.holdReason) {
      throw new MissingHoldReasonNoteError()
    }
    if (!validated.holdReasonNote) {
      throw new MissingHoldReasonNoteError()
    }
  }

  // Build update payload — only include hold fields when transitioning to on_hold
  const updates: Parameters<typeof repoUpdateRepair>[1] = { status: targetStatus }

  if (targetStatus === 'on_hold') {
    updates.holdReason = validated.holdReason as HoldReason | null
    updates.holdReasonNote = validated.holdReasonNote || null
  } else {
    // Clear hold fields when leaving on_hold state
    updates.holdReason = null
    updates.holdReasonNote = null
  }

  // Apply the update
  const updated = await repoUpdateRepair(id, updates)

  // Record in audit trail
  await repoRecordStatusTransition(updated.id, targetStatus)

  return toRepairDetail(updated)
}

/**
 * Update repair notes (customer-facing and/or internal).
 *
 * Both note types are always editable regardless of status.
 *
 * @param id - Repair identifier
 * @param input - Partial update with customerNotes and/or internalNotes
 * @returns The updated RepairDetail
 */
export async function updateRepairNotes(
  id: string,
  input: UpdateRepairInput,
): Promise<RepairDetail> {
  // Validate the update input
  const validated = updateRepairSchema.parse(input)

  // Look up current repair state
  const current = await repoFindRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }

  // Build partial update — only include fields that were provided
  const updates: Parameters<typeof repoUpdateRepair>[1] = {}

  if (validated.customerNotes !== undefined) {
    updates.customerNotes = validated.customerNotes || null
  }
  if (validated.internalNotes !== undefined) {
    updates.internalNotes = validated.internalNotes || null
  }
  if (validated.plannedDate !== undefined) {
    updates.plannedDate = validated.plannedDate ?? null
  }
  if (validated.pickupDate !== undefined) {
    updates.pickupDate = validated.pickupDate ?? null
  }

  // Apply the update
  const updated = await repoUpdateRepair(id, updates)

  return toRepairDetail(updated)
}

// ============================================================================
// Validation helpers
// ============================================================================

/** Validate that a status transition is allowed by the state machine. */
function validateTransition(from: RepairStatus, to: RepairStatus): void {
  // Cancel is always allowed from non-terminal states
  if (to === 'cancelled' && CANCEL_TARGETS.includes(from)) {
    return
  }

  const allowed = VALID_TRANSITIONS[from]
  if (!allowed || !allowed.includes(to)) {
    throw new InvalidStatusTransitionError(from, to)
  }
}

