/**
 * Create a new line item on a repair.
 *
 * Validates that the repair exists and is not completed, computes line totals,
 * and inserts the line item record.
 *
 * @param repairId - Parent repair identifier
 * @param input - Validated line item creation input (part or labor)
 * @returns The created RepairLineItem
 */
export async function createRepairLineItem(
  repairId: string,
  input: CreateRepairLineItemInput,
): Promise<typeof repairLineItems.$inferSelect> {
  // Validate the input schema
  const validated = createRepairLineItemSchema.parse(input)

  // Check that the repair exists and is not completed
  const current = await repoFindRepairById(repairId)
  if (!current) throw new RepairNotFoundError(repairId)
  if (current.status === 'completed') throw new RepairCompletedError(repairId)

  // Fetch VAT rate for total computation
  const vatRatesMap = await repoFindAllVatRates()
  const vatRateBps = vatRatesMap.get(validated.vatRateId) ?? 0

  // Compute line totals
  const totals = computeLineTotals(
    validated.unitPriceNet,
    validated.quantity,
    validated.discountPercent,
    vatRateBps
  )

  // Build insert data
  const now = Date.now()
  const lineItemId = crypto.randomUUID()
  const insertData = {
    id: lineItemId,
    repairId,
    lineType: validated.lineType,
    partId: validated.lineType === 'part' ? validated.partId : null,
    laborServiceId: validated.lineType === 'labor' ? validated.laborServiceId : null,
    description: validated.description,
    quantity: validated.quantity,
    unitPriceNet: validated.unitPriceNet,
    vatRateId: validated.vatRateId,
    discountPercent: validated.discountPercent ?? null,
    lineTotalNet: totals.net,
    lineTotalVat: totals.vat,
    lineTotalGross: totals.gross,
    minutesWorked: 'minutesWorked' in validated ? validated.minutesWorked ?? null : null,
    hourlyRateSnapshot: 'hourlyRateSnapshot' in validated ? validated.hourlyRateSnapshot ?? null : null,
    createdAt: now,
  }

  // Insert using raw SQL (to avoid Drizzle timestamp conversion issues)
  run(
    `INSERT INTO repair_line_items (id, repair_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, minutes_worked, hourly_rate_snapshot, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      insertData.id,
      insertData.repairId,
      insertData.lineType,
      insertData.partId,
      insertData.laborServiceId,
      insertData.description,
      insertData.quantity,
      insertData.unitPriceNet,
      insertData.vatRateId,
      insertData.discountPercent,
      insertData.lineTotalNet,
      insertData.lineTotalVat,
      insertData.lineTotalGross,
      insertData.minutesWorked,
      insertData.hourlyRateSnapshot,
      insertData.createdAt,
    ]
  )

  // Fetch and return the created record
  const [created] = await db.select().from(repairLineItems).where(eq(repairLineItems.id, lineItemId))
  return created!
}

/**
 * Update an existing repair line item.
 *
 * Recomputes line totals when quantity or unit price changes. For labor items,
 * also updates minutesWorked and hourlyRateSnapshot.
 *
 * @param repairId - Parent repair identifier (for status guard)
 * @param itemId - Line item identifier
 * @param input - Partial update fields
 * @returns The updated RepairLineItem
 */
export async function updateRepairLineItem(
  repairId: string,
  itemId: string,
  input: UpdateRepairLineItemInput,
): Promise<typeof repairLineItems.$inferSelect> {
  // Validate the update input
  const validated = updateRepairLineItemSchema.parse(input)

  // Check that the repair exists and is not completed
  const current = await repoFindRepairById(repairId)
  if (!current) throw new RepairNotFoundError(repairId)
  if (current.status === 'completed') throw new RepairCompletedError(repairId)

  // Find existing line item
  const existing = await repoFindLineItemById(itemId)
  if (!existing) throw new RepairLineItemNotFoundError(itemId)

  // Verify the line item belongs to this repair
  if (existing.repairId !== repairId) {
    throw new Error('Line item does not belong to the specified repair')
  }

  // Build update payload with recomputed totals (snake_case keys for SQL)
  const updates: Record<string, number | null> = {}
  let needsTotalsRecalculation = false

  if (validated.quantity !== undefined) {
    updates.quantity = validated.quantity
    needsTotalsRecalculation = true
  }
  if (validated.unitPriceNet !== undefined) {
    updates.unit_price_net = validated.unitPriceNet
    needsTotalsRecalculation = true
  }
  if (validated.discountPercent !== undefined) {
    updates.discount_percent = validated.discountPercent ?? null
    needsTotalsRecalculation = true
  }
  if (validated.minutesWorked !== undefined) {
    updates.minutes_worked = validated.minutesWorked ?? null
  }
  if (validated.hourlyRateSnapshot !== undefined) {
    updates.hourly_rate_snapshot = validated.hourlyRateSnapshot ?? null
  }

  // Recompute totals if needed (Drizzle returns camelCase property names)
  if (needsTotalsRecalculation) {
    const vatRatesMap = await repoFindAllVatRates()
    const vatRateBps = vatRatesMap.get(existing.vatRateId) ?? 0
    const quantity = validated.quantity ?? existing.quantity
    const unitPriceNet = validated.unitPriceNet ?? existing.unitPriceNet
    const discountPercent = validated.discountPercent !== undefined ? validated.discountPercent : (existing.discountPercent as number | null)

    const totals = computeLineTotals(unitPriceNet, quantity, discountPercent, vatRateBps)
    updates.line_total_net = totals.net
    updates.line_total_vat = totals.vat
    updates.line_total_gross = totals.gross
  }

  // Build SET clause for raw SQL update
  const setClauses: string[] = []
  const params: unknown[] = []

  for (const [key, value] of Object.entries(updates)) {
    if (value !== undefined) {
      setClauses.push(`${key} = ?`)
      params.push(value)
    }
  }

  if (setClauses.length > 0) {
    const sqlStr = `UPDATE repair_line_items SET ${setClauses.join(', ')} WHERE id = ?`
    run(sqlStr, [...params, itemId])
  }

  // Fetch and return the updated record
  const [updated] = await db.select().from(repairLineItems).where(eq(repairLineItems.id, itemId))
  if (!updated) throw new RepairLineItemNotFoundError(itemId)
  return updated
}

/**
 * Delete a repair line item.
 *
 * Guards against deletion when the repair is completed.
 *
 * @param repairId - Parent repair identifier (for status guard)
 * @param itemId - Line item identifier to delete
 * @returns The deleted RepairLineItem
 */
export async function deleteRepairLineItem(
  repairId: string,
  itemId: string,
): Promise<typeof repairLineItems.$inferSelect> {
  // Check that the repair exists and is not completed
  const current = await repoFindRepairById(repairId)
  if (!current) throw new RepairNotFoundError(repairId)
  if (current.status === 'completed') throw new RepairCompletedError(repairId)

  // Find existing line item
  const existing = await repoFindLineItemById(itemId)
  if (!existing) throw new RepairLineItemNotFoundError(itemId)

  // Verify the line item belongs to this repair
  if (existing.repairId !== repairId) {
    throw new Error('Line item does not belong to the specified repair')
  }

  // Delete using raw SQL
  run('DELETE FROM repair_line_items WHERE id = ?', [itemId])

  return existing
}

// ============================================================================
// Public API — Labor Services Catalog (GET /labor-services)
// ============================================================================

/**
 * List available labor services from the predefined catalog.
 *
 * Returns only active services, optionally filtered by billing type.
 *
 * @param filters - Optional filter criteria
 * @returns Array of active labor services
 */
export async function listLaborServices(filters: { billingType?: 'hourly' | 'fixed' } = {}): Promise<LaborService[]> {
  const rows = await repoFindLaborServices(filters.billingType)

  return rows.map((row) => ({
    id: row.id,
    name: row.name,
    description: row.description,
    billingType: row.billingType as 'hourly' | 'fixed',
    defaultRate: Number(row.defaultRate),
    isActive: Boolean(row.isActive),
  }))
}

/** Find a single labor service by ID. */
export async function getLaborServiceById(id: string): Promise<LaborService | null> {
  const client = sqliteDb as Database.Database
  const rows = client.prepare(
    `SELECT id, name, description, billing_type, default_rate, is_active FROM labor_services WHERE id = ?`,
  ).all([id]) as Array<{
    id: string
    name: string
    description: string | null
    billing_type: 'hourly' | 'fixed'
    default_rate: number
    is_active: number
  }>

  if (rows.length === 0) return null

  const row = rows[0]
  return {
    id: row.id,
    name: row.name,
    description: row.description,
    billingType: row.billing_type as 'hourly' | 'fixed',
    defaultRate: Number(row.default_rate),
    isActive: Boolean(row.is_active),
  }
}

export interface CreateLaborServiceInput {
  name: string
  description?: string
  billingType: 'hourly' | 'fixed'
  defaultRate: number
}

/** Create a new labor service. */
export async function createLaborService(input: CreateLaborServiceInput): Promise<LaborService> {
  const id = crypto.randomUUID()
  run(
    `INSERT INTO labor_services (id, name, description, billing_type, default_rate, is_active) VALUES (?, ?, ?, ?, ?, 1)`,
    [id, input.name.trim(), input.description?.trim() ?? null, input.billingType, input.defaultRate],
  )

  return {
    id,
    name: input.name.trim(),
    description: input.description?.trim() ?? null,
    billingType: input.billingType,
    defaultRate: input.defaultRate,
    isActive: true,
  }
}

export interface UpdateLaborServiceInput {
  name?: string
  description?: string
  billingType?: 'hourly' | 'fixed'
  defaultRate?: number
}

/** Update an existing labor service. */
export async function updateLaborService(id: string, input: UpdateLaborServiceInput): Promise<LaborService> {
  const existing = await getLaborServiceById(id)
  if (!existing) throw new LaborServiceNotFoundError(id)

  const name = input.name !== undefined ? input.name.trim() : existing.name
  const description = input.description !== undefined ? (input.description.trim() || null) : existing.description
  const billingType = input.billingType ?? existing.billingType
  const defaultRate = input.defaultRate ?? existing.defaultRate

  run(
    `UPDATE labor_services SET name = ?, description = ?, billing_type = ?, default_rate = ? WHERE id = ?`,
    [name, description, billingType, defaultRate, id],
  )

  return {
    id,
    name,
    description,
    billingType,
    defaultRate,
    isActive: existing.isActive,
  }
}

/** Soft-delete a labor service by setting is_active = 0. */
export async function deactivateLaborService(id: string): Promise<void> {
  const existing = await getLaborServiceById(id)
  if (!existing) throw new LaborServiceNotFoundError(id)

  run(`UPDATE labor_services SET is_active = 0 WHERE id = ?`, [id])
}

// ============================================================================
// Public API — Worker Assignment (PATCH /repairs/:id/assign)
// ============================================================================

/**
 * Assign or reassign a worker to a repair.
 *
 * The assignedTo field is always editable regardless of status, allowing
 * managers to rebalance workload at any time.
 *
 * @param id - Repair identifier
 * @param input - Worker assignment input (UUID or null)
 * @returns The updated RepairDetail
 */
export async function assignWorkerToRepair(
  id: string,
  input: AssignWorkerInput,
): Promise<{
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: HoldReason | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}> {
  // Validate the assignment input
  const validated = assignWorkerSchema.parse(input)

  // Look up current repair state
  const current = await repoFindRepairById(id)
  if (!current) throw new RepairNotFoundError(id)

  // Update assignedTo using raw SQL
  run('UPDATE repairs SET assigned_to = ? WHERE id = ?', [validated.assignedTo, id])

  // Fetch and return the updated repair
  const [updated] = await db.select().from(repairs).where(eq(repairs.id, id))
  if (!updated) throw new RepairNotFoundError(id)

  return {
    id: updated.id,
    bicycleId: updated.bicycleId,
    assignedTo: updated.assignedTo,
    status: updated.status as RepairStatus,
    customerNotes: updated.customerNotes,
    internalNotes: updated.internalNotes,
    holdReason: updated.holdReason as HoldReason | null,
    holdReasonNote: updated.holdReasonNote,
    plannedDate: updated.plannedDate ?? null,
    pickupDate: updated.pickupDate ?? null,
    completedAt: updated.completedAt ?? null,
    createdAt: updated.createdAt,
  }
}

// ============================================================================
// Error types — work logs / timer
// ============================================================================

/** Thrown when a work log is not found. */
export class WorkLogNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Work log not found: ${id}`)
    this.name = 'WorkLogNotFoundError'
  }
}

// ============================================================================
// Repository layer — work logs (raw SQL to avoid Drizzle timestamp conversion issues)
// ============================================================================

/** Find a single work log by ID. Returns epoch ms timestamps (not Date objects). */
async function repoFindWorkLogById(id: string): Promise<{
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
} | undefined> {
  const client = sqliteDb as Database.Database
  const [row] = client.prepare(
    'SELECT id, repair_id AS repairId, user_id AS userId, started_at AS startedAt, ended_at AS endedAt FROM work_logs WHERE id = ?'
  ).all(id) as Array<{ id: string; repairId: string; userId: string; startedAt: number | null; endedAt: number | null }>

  return row ?? undefined
}

/** Create a new work log entry using raw SQL (avoids Drizzle Date conversion issues). */
async function repoCreateWorkLog(data: {
  id: string
  repairId: string
  userId: string
  startedAt: number
}): Promise<string> {
  run(
    'INSERT INTO work_logs (id, repair_id, user_id, started_at, ended_at) VALUES (?, ?, ?, ?, NULL)',
    [data.id, data.repairId, data.userId, data.startedAt]
  )
  return data.id
}

/** Update a work log's endedAt timestamp using raw SQL. */
async function repoUpdateWorkLogEndedAt(workLogId: string, endedAt: number): Promise<void> {
  run('UPDATE work_logs SET ended_at = ? WHERE id = ?', [endedAt, workLogId])
}

// ============================================================================
// Public API — Work Timer (manual start/stop)
// ============================================================================

/** Input for starting a work timer session */
export interface StartWorkTimerInput {
  /** User ID of the technician starting the timer */
  userId: string
}

/** Output shape from stopWorkTimer — includes duration calculation */
export interface WorkLogWithDuration {
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
  /** Duration in milliseconds (only when endedAt is set) */
  durationMs?: number
}

/**
 * Start a manual work timer for a repair.
 *
 * Creates a new work log entry with the current timestamp as startedAt.
 * Multiple sessions can be open simultaneously on the same repair — this is
 * intentional: technicians may switch between tasks and want to track each
 * session independently. The frontend should only allow one "active" timer
 * at a time by checking for null endedAt, but the service layer does not
 * enforce single-session semantics.
 *
 * @param repairId - Repair identifier
 * @param input - Technician user ID
 * @returns Created work log entry with startedAt timestamp and endedAt = null
 */
export async function startWorkTimer(
  repairId: string,
  userId: string,
): Promise<WorkLogWithDuration> {
  // Verify the repair exists
  const repair = await repoFindRepairById(repairId)
  if (!repair) {
    throw new RepairNotFoundError(repairId)
  }

  // Create work log entry with current timestamp
  const now = Date.now()
  const workLogId = crypto.randomUUID()
  await repoCreateWorkLog({ id: workLogId, repairId, userId, startedAt: now })

  return {
    id: workLogId,
    repairId,
    userId,
    startedAt: now,
    endedAt: null,
  }
}

